  PERFORM coaching.apply_candidate_exercise_card_v1($card_1_payload${"migrationKey":"717_coaching_a_skip_source_95_candidate_materialization","researchVersion":"2026-07-25.9","definition":{"facilityId":1,"legacyExerciseId":95,"preserveLegacyExerciseId":true,"slug":"a-skip","canonicalName":"A-Skip","displayName":"A-Skip","aliases":["A Skip","A-Skip Rhythm Punch","A-Skip Snap Down","Sprint A-Skip"],"description":"Travel forward on a clear level lane through alternating step-hop cycles. Each side performs one supported step followed by a brief flight and landing before the opposite side repeats; recover the thigh toward the declared landmark, return the contact close beneath the body, stay tall, and coordinate opposite arm and leg. One cycle is one step-hop landing on each side. This excludes no-flight A-March, running, B-Skip, stationary skipping, wall support, resistance, obstacle spacing, a terminal sprint, and assessment.","familyKey":"traveling_alternating_a_skip","schemaVersion":"2.0.0","cardVersion":4,"status":"review","identityContract":"traveling_alternating_step_hop_cycles_with_brief_flight_assigned_thigh_recovery_close_under_body_landing_and_reciprocal_arm_action","confidence":{"content":78,"scoring":50,"media":50},"movementPatterns":["locomote","jump","land","sprint_contact_learning"],"bodyRegions":["foot","ankle","calf","knee","thigh","hip","core","upper_arm"],"requiredEquipment":["10_to_20_metre_clear_lane","safe_finish_zone"],"optionalEquipment":["cones","cadence_feedback","video"],"environment":{"surface":"clear, level, dry, non-slip, impact-appropriate lane","space":"one protected 10-20 metre lane with a safe finish zone and no cross traffic","stationCapacity":1,"inspection":["surface traction, debris, moisture, and clearance","defined lane and finish zone","footwear, communication, entry, exit, and coach sightline"],"changeRule":"Changing flight, step-hop contact sequence, support, travel, lane, thigh target, arm action, cadence, resistance, cue, dose, surface, footwear, intent, or symptoms requires revalidation."},"population":{"exerciseCardDoesNotClassifyParticipants":true,"readinessIsWorkoutInput":true,"selectionPrerequisites":["safe lane and comfortable pain-free low hop","can demonstrate controlled no-flight A-March before adding flight","understands alternating step-hop rhythm, contact count, stop signal, and exit","session foot, calf, landing, impact, and technical-fatigue budgets fit"],"excludeOrEscalate":["pain, limp, repeated rhythm loss, unsafe lane, or communication conflict","sharp, increasing, unfamiliar, neurologic, circulation, breathing, chest, balance, or coordination concern","participant requests stop"],"notEstablishedByEvidence":["universal thigh height, cadence, lane length, contact cap, dose, recovery, sprint outcome, readiness threshold, or clinical clearance"]},"provenance":{"legacySources":[95,717,925,1118],"identityAuthority":"Source 95 and the A-series sprint-drills research packet: A-Skip is an alternating step-hop with flight; punch and snap-down cue emphasis preserve identity while no-flight marching, running, B-Skip, support, resistance, spacing, and terminal transitions do not.","canonicalAuthoredFromResearch":true,"primaryIdentitySource":"https://pubmed.ncbi.nlm.nih.gov/33217086/","primaryIdentitySourceStatus":"candidate_research_evidence_unreviewed","externalPlaybackVerificationPerformed":false,"oEmbedMetadataChecked":false,"humanReviewRequired":true,"approvalsCreated":false,"publicationQuarantined":true},"anatomy":{"primaryMuscles":["hip_flexors","gluteal_complex","hamstring_complex","soleus","gastrocnemius"],"secondaryMuscles":["quadriceps","tibialis_anterior","intrinsic_foot_muscle_system","gluteus_medius","trunk_stabilizers","shoulder_girdle"],"joints":["metatarsophalangeal","talocrural_ankle","knee","hip","thoracolumbar_spine","shoulder"],"jointActions":["alternating_hip_flexion_extension","alternating_knee_flexion_extension","ankle_dorsiflexion_plantarflexion_control","al