ransitionSeconds":30,"clearanceRequired":true},"substitutionIds":[],"timeModel":{"setupSeconds":45,"perSetSeconds":90,"resetSeconds":60},"doseScaling":{"reduce":"shorten the pass, reduce contacts or cadence, extend rest, or use another reviewed task after revalidation","doNotAutoProgress":"Do not add B-Skip mechanics, running, resistance, a wall, obstacle, terminal sprint, or compound transition automatically."},"measurement":{"record":["contactsPerSide","distance","cadence","contactReach","contactSound","rhythmQuality","symptoms","rest"]},"supportPrompts":{"athlete":"Crisp step-hop, not a run.","coach":"Stop when the exact alternating flight-and-landing rhythm changes."}}]}],"testPacket":{"auditVersion":"canonical-card-audit-v1","status":"quarantined","humanReviewRequired":true,"checks":{"identity":"candidate_complete","taxonomy":"candidate_complete","difficulty":"candidate_complete","media":"human_review_required","relationships":"human_review_required","calibration":"human_review_required","publication":"human_review_required"},"blockingIssues":[{"code":"CARD-MEDIA-01","severity":"P0","message":"Exact-match media requires human review."},{"code":"CARD-GRAPH-03","severity":"P1","message":"Relationships require human review."},{"code":"CARD-CALIBRATION-01","severity":"P1","message":"Independent score calibration is required."},{"code":"CARD-PUBLISH-01","severity":"P0","message":"Publication requires current two-person approval."}]},"calibrations":[{"variantId":"95000000-0000-4000-8000-000000000002","dimension":"baseOverallDifficulty","proposedScore":52,"anchorTier":60,"rationale":"Candidate anchor generated from the exact Traveling Alternating Step-Hop A-Skip task contract. Independent human calibration remains required."},{"variantId":"95000000-0000-4000-8000-000000000002","dimension":"technicalComplexity","proposedScore":52,"anchorTier":60,"rationale":"Candidate anchor generated from the exact Traveling Alternating Step-Hop A-Skip task contract. Independent human calibration remains required."},{"variantId":"95000000-0000-4000-8000-000000000002","dimension":"supervisionDemand","proposedScore":36,"anchorTier":40,"rationale":"Candidate anchor generated from the exact Traveling Alternating Step-Hop A-Skip task contract. Independent human calibration remains required."},{"variantId":"95000000-0000-4000-8000-000000000002","dimension":"failureConsequence","proposedScore":28,"anchorTier":20,"rationale":"Candidate anchor generated from the exact Traveling Alternating Step-Hop A-Skip task contract. Independent human calibration remains required."},{"variantId":"95000000-0000-4000-8000-000000000002","dimension":"impact","proposedScore":25,"anchorTier":20,"rationale":"Candidate anchor generated from the exact Traveling Alternating Step-Hop A-Skip task contract. Independent human calibration remains required."},{"variantId":"95000000-0000-4000-8000-000000000002","dimension":"workCapacityDemand","proposedScore":26,"anchorTier":20,"rationale":"Candidate anchor generated from the exact Traveling Alternating Step-Hop A-Skip task contract. Independent human calibration remains required."}],"evidence":[{"sectionKey":"identity","sourceUrl":"https://pubmed.ncbi.nlm.nih.gov/41209369/","sourceTitle":"Development and Validation of a Running Drill Test Battery to Predict 5 m and 20 m Sprint Performance","sourcePublisher":"International Journal of Exercise Science","sourceKind":"peer_reviewed_research","evidenceQuality":82,"claims":["A published running-drill test battery defines A-skip with observable arm action, thigh motion, support-leg behavior, contact location, foot direction, posture, and swing-path criteria.","A-Skip must state whether the task is a no-flight march, an alternating step-hop skip, a pogo skip, a constrained ladder or gate variant, or a compound transition; coaching words such as punch, snap, rhythm, projection, and mobility do not establish a separate identity."]},{"sectionKey":"taxonomy","sourceUrl":"https://pmc.ncbi.nlm.nih.gov/articles/PMC6872694/","sourceTitle":"The Training and Development of Elite Sprint Performance: an Integration of Scientific and Best Practice Literature","sourcePublisher":"Sports Medicine - Open","sourceKind":"peer_reviewed_research","evidenceQuality":90,"claims":["Sprint drills are commonly used as controllable, low-speed tasks for posture, limb configuration, rhythm, and proprioceptive emphasis, but their mechanics must resemble the intended target when transfer is claimed.","A-Skip belongs to no-flight alternating sprint-mechanics marching, alternating step-hop skipping, an external-spacing variant, or a separately defined compound progression; it is not itself sprinting, maximal-speed work, or a jump-height test."]},{"sectionKey":"anatomy","sourceUrl":"https://pubmed.ncbi.nlm.nih.gov/28632055/","sourceTitle":"Muscle activity in sprinting: a review","sourcePublisher":"Sports Biomechanics","sourceKind":"peer_reviewed_research","evidenceQuality":86,"claims":["Sprint muscle activity is phase-specific and distributed across lower-limb and trunk musculature rather than isolated to a single high-knee muscle action.","The card should identify hip flexors, gluteus maximus, hamstrings, quadriceps, soleus, gastrocnemius, tibialis anterior, intrinsic foot, frontal-plane pelvic stabilizers, trunk, and shoulder-girdle roles in proportion to the actual march, skip, or constraint."]},{"sectionKey":"biomechanics","sourceUrl":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8008308/","sourceTitle":"Kinematic Stride Characteristics of Maximal Sprint Running of Elite Sprinters – Verification of the Swing-Pull Technique","sourcePublisher":"Journal of Human Kinetics","sourceKind":"peer_reviewed_research","evidenceQuality":84,"claims":["During maximal sprinting, active foot velocity before contact, contact near the projected center of mass, hip-extension velocity, and controlled support-leg flexion can influence braking and contact behavior.","A march or skip can constrain posture, recovery, contact placement, and arm-leg timing, but visual similarity cannot prove sprint force, joint stiffness, or transfer; cue only observable execution of the drill."]},{"sectionKey":"difficulty","sourceUrl":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8553457/","sourceTitle":"Application of Leg, Vertical, and Joint Stiffness in Running Performance: A Literature Overview","sourcePublisher":"Journal of Healthcare Engineering","sourceKind":"peer_reviewed_research","evidenceQuality":86,"claims":["Whole-limb stiffness changes with task, speed, maturity, fatigue, and measurement method and cannot be inferred as a fixed quality from a drill label.","Exercise difficulty must directly score technical complexity, physical and absolute-load demand, coordination, supervision, failure consequence, impact, work-capacity demand, and overall difficulty; athlete experience remains programming context."]},{"sectionKey":"load_fatigue_recovery","sourceUrl":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8938535/","sourceTitle":"Effects of Plyometric Training on Lower Body Muscle Architecture, Tendon Structure, Stiffness and Physical Performance: A Systematic Review and Meta-analysis","sourcePublisher":"Sports Medicine - Open","sourceKind":"peer_reviewed_research","evidenceQuality":91,"claims":["Repeated flight contacts can contribute meaningful muscle-tendon loading even when external load and amplitude are low.","A-Skip needs pass distance, total and per-leg contacts, flight or no-flight status, surface, footwear, spacing constraint, cadence or intent, technical-fatigue markers, recovery, and weekly impact accounting rather than an unqualified repetition or work interval."]},{"sectionKey":"constraints","sourceUrl":"https://www.nsca.com/globalassets/education/nsca-coach/nsca-coach-5.4.pdf","sourceTitle":"Developing Linear Speed","sourcePublisher":"National Strength and Conditioning Association","sourceKind":"professional_standard","evidenceQuality":82,"claims":["Linear-speed preparation requires suitable space, safe start and finish zones, progressive intensity, adequate recovery, and coaching matched to the intended movement quality.","Require a level, dry, non-slip lane, safe spacing and finish, suitable footwear, secured flat ladder or visible gates only when prescribed, and readiness for the contact amplitude and coordination actually used."]},{"sectionKey":"dosage","sourceUrl":"https://worldathletics.org/personal-best/performance/jereem-richards-games-drills-develop-speed","sourceTitle":"Jereem Richards’ games and drills to help develop speed","sourcePublisher":"World Athletics","sourceKind":"governing_body","evidenceQuality":77,"claims":["World Athletics gives two passes over 10 to 20 metres as an example for progressive running drills and directs athletes to learn the movement before increasing cadence.","Use short passes, metres, explicit contacts, cadence or execution intent, and recovery; no-flight marches may use walk-back recovery, while skips and compound transitions need impact-aware volume and enough rest to preserve rhythm."]},{"sectionKey":"instructions","sourceUrl":"https://pubmed.ncbi.nlm.nih.gov/41209369/","sourceTitle":"Development and Validation of a Running Drill Test Battery to Predict 5 m and 20 m Sprint Performance","sourcePublisher":"International Journal of Exercise Science","sourceKind":"peer_reviewed_research","evidenceQuality":82,"claims":["Published A-skip criteria include relaxed arms and shoulders, coordinated arm action without excessive midline crossing, a defined thigh path, forward-facing feet, contact near the body's vertical projection, and completion of support-leg extension.","Use a small cue set: stay tall or use the explicitly assigned projection, lift to the assigned landmark, keep the ankle prepared without forcing the heel, step or skip close beneath the body, coordinate opposite arm and leg, and preserve the defined march or step-hop rhythm."]},{"sectionKey":"safety_stop_rules","sourceUrl":"https://pubmed.ncbi.nlm.nih.gov/37989833/","sourceTitle":"Ankle and Plantar Flexor Muscle-Tendon Unit Function in Sprinters: A Narrative Review","sourcePublisher":"Sports Medicine","sourceKind":"peer_reviewed_research","evidenceQuality":89,"claims":["Foot and plantar-flexor demands differ across locomotor tasks and sprint phases, so repeated contacts should not be represented as uniformly negligible load.","Stop for foot, shin, calf, Achilles, hamstring, knee, hip, or back pain; limping; loss of balance; repeated reaching; forced or painful foot strike; loud contacts; cadence or posture loss; ladder contact; displaced equipment; or an unsafe finish."]},{"sectionKey":"programming","sourceUrl":"https://pubmed.ncbi.nlm.nih.gov/41209369/","sourceTitle":"Development and Validation of a Running Drill Test Battery to Predict 5 m and 20 m Sprint Performance","sourcePublisher":"International Journal of Exercise Science","sourceKind":"peer_reviewed_research","evidenceQuality":82,"claims":["The study found good overall inter-rater reliability for its A-skip scoring criteria but no statistically significant association between A-skip score and 5 m or 20 m sprint performance in its sample.","A-Skip should be programmed as a fresh coordination, position, rhythm, or warm-up constraint with an explicit athlete-specific purpose; do not promise faster sprinting, better acceleration, jump height, or approach transfer from the drill alone."]},{"sectionKey":"athlete_support","sourceUrl":"https://pubmed.ncbi.nlm.nih.gov/41209369/","sourceTitle":"Development and Validation of a Running Drill Test Battery to Predict 5 m and 20 m Sprint Performance","sourcePublisher":"International Journal of Exercise Science","sourceKind":"peer_reviewed_research","evidenceQuality":82,"claims":["Clear, criterion-referenced movement elements make drill execution more observable than vague labels or outcome promises.","Show side and rear views, flight or no-flight contacts, thigh landmark, foot path, arm action, pass distance, gate or ladder pattern, finish, and one regression; explain that higher knees and faster feet are not automatically better."]},{"sectionKey":"coach_support","sourceUrl":"https://pubmed.ncbi.nlm.nih.gov/41209369/","sourceTitle":"Development and Validation of a Running Drill Test Battery to Predict 5 m and 20 m Sprint Performance","sourcePublisher":"International Journal of Exercise Science","sourceKind":"peer_reviewed_research","evidenceQuality":82,"claims":["A-skip ratings were more reliable for upper-extremity criteria than lower-extremity criteria, supporting explicit observation criteria and trained raters rather than a global visual impression.","Provide side and rear observation, pass and contact counts, left-right comparison, exact equipment spacing, optional slow-motion video, cue-response notes, and a distinction between a coached drill constraint and measured sprint biomechanics."]},{"sectionKey":"accessibility","sourceUrl":"https://www.nsca.com/globalassets/about/position-statements/position_stand_youth_resistance_training---2009.pdf","sourceTitle":"Youth Resistance Training: Updated Position Statement Paper From the NSCA","sourcePublisher":"National Strength and Conditioning Association","sourceKind":"professional_standard","evidenceQuality":88,"claims":["Exercise selection and progression should match readiness, technical competence, supervision, equipment scale, and the individual's physical and psychosocial context.","Accessibility options include in-place rehearsal, slower cadence, shorter passes, lower thigh target, marching instead of skipping, floor marks instead of a raised ladder, fewer contacts, longer recovery, quieter instruction, and additional demonstration."]},{"sectionKey":"alternates","sourceUrl":"https://pmc.ncbi.nlm.nih.gov/articles/PMC6872694/","sourceTitle":"The Training and Development of Elite Sprint Performance: an Integration of Scientific and Best Practice Literature","sourcePublisher":"Sports Medicine - Open","sourceKind":